from functools import lru_cache
from itertools import product
R = PolynomialRing(QQ, 's')
s = R.gen()
z = R.zero()
base = [(kind,powr,c) for kind,powr in [(0,0),(0,1),(0,2),(1,0),(1,1)] for c in range(3)]
N = len(base)
deg = [int(a[0])-1 for a in base]
ix = {b:i for i,b in enumerate(base)}
def ze(): return vector(R,N)
def zp(): return vector(R,2*N)
def unit(i):
    a=ze(); a[i]=1; return a
units=[unit(i) for i in range(N)]
def sig(n): return QQ(-1) if int(n)%2 else QQ(1)
def levi(a,b,c):
    if len({a,b,c})<3: return 0
    return 1 if (a,b,c) in [(0,1,2),(1,2,0),(2,0,1)] else -1
def dd(a):
    out=ze()
    for i,coef in enumerate(a):
        kind,k,c=base[i]
        if coef and kind==0 and k:
            out[ix[(1,k-1,c)]] += k*coef
    return out
def hh(a):
    out=ze()
    for i,coef in enumerate(a):
        kind,k,c=base[i]
        if coef and kind==1:
            out[ix[(0,k+1,c)]] += coef/QQ(k+1)
    return out
def pp(a):
    return a-dd(hh(a))-hh(dd(a))
def bracket(a,b):
    out=ze()
    for i,ai in enumerate(a):
        if not ai: continue
        ki,ni,ci=base[i]
        for j,bj in enumerate(b):
            if not bj: continue
            kj,nj,cj=base[j]
            kk,nn=ki+kj,ni+nj
            if kk>1 or nn>2-kk: continue
            for c in range(3):
                ec=levi(ci,cj,c)
                if ec: out[ix[(kk,nn,c)]] += ai*bj*ec
    return out
def q2(a,b,ea):
    return sig(ea)*bracket(a,b)
def ab(w): return (vector(R,w[:N]),vector(R,w[N:]))
def path(a,b): return vector(R,list(a)+list(b))
def dq(w):
    a,b=ab(w)
    return path(dd(a),vector(R,[t.derivative(s) for t in a])-dd(b))
def qb(w,u,ew):
    a,b=ab(w); c,e=ab(u)
    # Unshifted degree of w is ew+1; ds is written on the left.
    return sig(ew)*path(bracket(a,c),bracket(b,c)+sig(ew+1)*bracket(a,e))
def hkernel(w):
    a,b=ab(w)
    intb=[t.integral(s) for t in b]
    return path(vector(R,[t-t(1) for t in intb]),ze())
def lift(a): return path(pp(a)+s*(a-pp(a)),hh(a))
def endpoint(w,t):
    a,b=ab(w); return vector(R,[u(t) for u in a])
def apply2(fun,a,b):
    out=zp()
    for i,ai in enumerate(a):
        if ai:
            for j,bj in enumerate(b):
                if bj: out += ai*bj*fun(i,j)
    return out
def apply3(fun,a,b,c):
    out=zp()
    for i,ai in enumerate(a):
        if ai:
            for j,bj in enumerate(b):
                if bj:
                    for k,ck in enumerate(c):
                        if ck: out += ai*bj*ck*fun(i,j,k)
    return out
@lru_cache(None)
def residual2(i,j):
    return qb(lift(units[i]),lift(units[j]),deg[i])-lift(q2(units[i],units[j],deg[i]))
@lru_cache(None)
def f2(i,j): return -hkernel(residual2(i,j))
def partitions3(i,j,k):
    return [(i,j,k,QQ(1)),(i,k,j,sig(deg[j]*deg[k])),(j,k,i,sig(deg[i]*(deg[j]+deg[k])))]
@lru_cache(None)
def residual3(i,j,k):
    out=zp()
    for a,b,c,sg in partitions3(i,j,k):
        out += sg*(qb(f2(a,b),lift(units[c]),deg[a]+deg[b])
                  -apply2(f2,q2(units[a],units[b],deg[a]),units[c]))
    return out
@lru_cache(None)
def f3(i,j,k): return -hkernel(residual3(i,j,k))
def defect2(i,j):
    return (dq(f2(i,j))-apply2(f2,dd(units[i]),units[j])
            -sig(deg[i])*apply2(f2,units[i],dd(units[j]))+residual2(i,j))
def defect3(i,j,k):
    return (dq(f3(i,j,k))-apply3(f3,dd(units[i]),units[j],units[k])
           -sig(deg[i])*apply3(f3,units[i],dd(units[j]),units[k])
           -sig(deg[i]+deg[j])*apply3(f3,units[i],units[j],dd(units[k]))+residual3(i,j,k))
def closed3(i,j,k):
    return (dq(residual3(i,j,k))+apply3(residual3,dd(units[i]),units[j],units[k])
           +sig(deg[i])*apply3(residual3,units[i],dd(units[j]),units[k])
           +sig(deg[i]+deg[j])*apply3(residual3,units[i],units[j],dd(units[k])))
pair_ids=list(product(range(N),repeat=2))
triple_ids=list(product(range(N),repeat=3))
# A non-strict homotopy inverse, with an actual compatible inclusion.
dG=matrix(QQ,3); dG[2,1]=1
dP=matrix(QQ,5); dP[2,1]=1; dP[4,3]=1
inc=matrix(QQ,5,3); inc[0,0]=inc[1,1]=inc[2,2]=1
HG=matrix(QQ,3); HG[1,2]=1
HP=matrix(QQ,5); HP[1,2]=1; HP[3,4]=1; HP[1,4]=1
p=matrix(QQ,3,5); p[0,0]=1; p[1,3]=-1; p[2,4]=-1
IG=identity_matrix(QQ,3); IP=identity_matrix(QQ,5)
DF=block_matrix([[dG,zero_matrix(QQ,3,5)],[inc,-dP]])
KF=block_matrix([[HG,p],[zero_matrix(QQ,5,3),-HP]])
KFN=KF*DF*KF
# Polynomial interval kernel model: g, v0, v1, b0, b1, b2.
sizes=[3,5,5,5,5,5]
off=[0]
for n in sizes: off.append(off[-1]+n)
nt=off[-1]
def blocks_to_matrix(rows):
    return block_matrix(QQ,rows)
Z35=zero_matrix(QQ,3,5); Z53=zero_matrix(QQ,5,3); Z55=zero_matrix(QQ,5,5)
dk=blocks_to_matrix([
 [dG,Z35,Z35,Z35,Z35,Z35],
 [Z53,dP,Z55,Z55,Z55,Z55],
 [Z53,Z55,dP,Z55,Z55,Z55],
 [-inc,IP,Z55,-dP,Z55,Z55],
 [Z53,-2*IP,2*IP,Z55,-dP,Z55],
 [Z53,Z55,-3*IP,Z55,Z55,-dP]
])
piw=blocks_to_matrix([
 [IG,Z35,Z35,Z35,Z35,Z35],
 [Z53,Z55,Z55,-IP,-IP/2,-IP/3]
])
jw=blocks_to_matrix([
 [IG,Z35],[Z53,Z55],[Z53,Z55],[Z53,-IP],[Z53,Z55],[Z53,Z55]
])
kw=zero_matrix(QQ,nt)
kw[off[1]:off[2],off[4]:off[5]]=-IP/2
kw[off[1]:off[2],off[5]:off[6]]=-IP/3
kw[off[2]:off[3],off[5]:off[6]]=-IP/3
hk=kw+jw*KFN*piw
# Noncommuting chain smoothers; no projection hypothesis.
hA=zero_matrix(QQ,5); hA[1,2]=QQ(1)/2; hA[3,4]=1
hB=zero_matrix(QQ,5); hB[1,4]=1; hB[3,2]=1
FA=IP-dP*hA-hA*dP; FB=IP-dP*hB-hB*dP
hAB=hB+hA*FB
hBA=hA+hB*FA
F=inc*p
# Relative exterior trace is the common harmonic coordinate.
rG=matrix(QQ,1,3,[1,0,0]); rP=matrix(QQ,1,5,[1,0,0,0,0])

